#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_wipe_percent;
uniform float amzp_edge_softness;
uniform float amzp_frequency;
uniform float amzp_freq_rel_x;
uniform float amzp_octaves;
uniform float amzp_layers;
uniform float amzp_seed;
uniform float amzp_plasma_grad;
uniform float amzp_plasma_grad_angle;
uniform float amzp_grad_add;
uniform float amzp_grad_angle;
uniform float amzp_shift_x;
uniform float amzp_shift_y;
uniform float amzp_phase_start;
uniform float amzp_phase_speed;
uniform float amzp_warp_strength;
uniform float amzp_warp_freq;
uniform float amzp_lines_enable;
uniform float amzp_lines_density;
uniform float amzp_lines_width;
uniform float amzp_lines_alpha;
layout(color) uniform half4 amzp_fill_color;
uniform float amzp_fill_alpha;




    const float PI = 3.14159265358979323846;
    float hash11(float n){ return fract(sin(n * 127.1 + 311.7) * 43758.5453123); }

    float2x2 rot(float a){ float c = cos(a), s = sin(a); return float2x2(c,-s,s,c); }


    float plasmaBase(float2 p, float t){
      float val = 0.0;
      val += sin(p.x + t);
      val += sin(p.y + t*1.13);
      val += sin((p.x + p.y)*0.7 + t*0.7);
      return val * (1.0/3.0);
    }


    float fbmPlasma(float2 p, float t, int oct){
      float sum = 0.0;
      float amp = 0.5;
      float freq = 1.0;
      for(int i=0;i<8;i++){
        if(i>=oct) break;
        float ang = hash11(float(i) + amzp_seed) * 6.2831853;
        float2 q = rot(ang) * p * freq + float2(hash11(float(i)+amzp_seed*2.0), hash11(float(i)+amzp_seed*3.0));
        sum += amp * plasmaBase(q, t * (1.0 + 0.35*float(i)) + float(i));
        freq *= 1.9;
        amp *= 0.55;
      }
      return sum;
    }

    void amzRender(){
      float2 uv = amzScreenNorm();

      float2 shiftUV = float2(amzp_shift_x / max(screen.zw.x, 1.0), amzp_shift_y / max(screen.zw.y, 1.0));
      uv += shiftUV;


      float baseFreq = max(amzp_frequency, 0.0001);
      float fx = baseFreq * max(amzp_freq_rel_x, 0.0001) * (screen.zw.x / max(screen.zw.y, 1.0));
      float fy = baseFreq;
      float2 p = float2(uv.x * fx, uv.y * fy);

      float t = amzp_phase_start + time * amzp_phase_speed;


      float layersF = float(amzp_layers);
      float layerSum = 0.0;
      for(float i=0.0;i<16.0;i+=1.0){
        if(i>=layersF) break;
        float ang = i * (PI * 2.0 / max(layersF,1.0));
        float2 dir = rot(ang) * float2(1.0, 0.0);
        float off = hash11(i + amzp_seed) * 10.0;
        layerSum += sin(dot(p, dir) + t + off);
      }
      layerSum /= max(layersF, 1.0);


      float2 warpVec;
      warpVec.x = fbmPlasma(p * amzp_warp_freq + 17.0, t*0.8, int(amzp_octaves));
      warpVec.y = fbmPlasma(p * (amzp_warp_freq*1.3) - 11.0, t*0.8 + 3.14, int(amzp_octaves));
      p += amzp_warp_strength * warpVec;

      float n = 0.55 * layerSum + 0.45 * fbmPlasma(p, t, int(amzp_octaves));


      float gradA = amzp_plasma_grad_angle * (PI/180.0);
      float2 gdir = float2(cos(gradA), sin(gradA));
      n += amzp_plasma_grad * dot(uv - 0.5, gdir);


      float gA2 = amzp_grad_angle * (PI/180.0);
      float2 gdir2 = float2(cos(gA2), sin(gA2));
      n += amzp_grad_add * dot(uv - 0.5, gdir2);


      n = 0.5 + 0.5 * clamp(n, -1.0, 1.0);


      float th = clamp(amzp_wipe_percent / 100.0, 0.0, 1.0);
      float s = max(amzp_edge_softness, 0.0);
      float mask = smoothstep(th - s, th + s, n);


      float lc = 0.0;
      if((amzp_lines_enable>0.5)){
        float den = max(amzp_lines_density, 0.001);
        float stripe = fract(n * den);
        float w = max(amzp_lines_width, 0.0001);
        float line = 1.0 - smoothstep(0.5 - w*0.5, 0.5 + w*0.5, stripe);
        lc = clamp(line, 0.0, 1.0) * amzp_lines_alpha;
      }


      float4 src = amzTexture(0, amzScreenNorm());
      float4 revealed = float4(src.rgb * src.a, src.a) * mask;
      float4 fill = float4(amzp_fill_color.rgb * amzp_fill_alpha, amzp_fill_alpha) * (1.0 - mask);
      float4 base = revealed + fill;


      float4 lines = float4(float3(0.0), lc);
      float4 outc = lines + base * (1.0 - lines.a);
      amzOutput = outc;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

